"""Campaign draft store backed by SQLite (stdlib only)."""
from __future__ import annotations

import json
import sqlite3
import uuid
from dataclasses import dataclass, field
from typing import Any, Dict, List, Optional, Tuple


class StoreError(Exception):
    """Base error for the store."""


class ValidationError(StoreError):
    """Raised when input fails validation."""


class NotFoundError(StoreError):
    """Raised when a record does not exist."""


class ConflictError(StoreError):
    """Raised on optimistic version mismatch or duplicate idempotency key."""


@dataclass
class Draft:
    draft_id: str
    workspace: str
    owner_team: int
    budget: int
    status: str
    version: int
    payload: Dict[str, Any] = field(default_factory=dict)


_SCHEMA = """
CREATE TABLE IF NOT EXISTS drafts (
    draft_id      TEXT PRIMARY KEY,
    workspace     TEXT NOT NULL,
    owner_team    INTEGER NOT NULL,
    budget        INTEGER NOT NULL,
    status        TEXT NOT NULL,
    version       INTEGER NOT NULL,
    payload       TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS idempotency (
    key           TEXT PRIMARY KEY,
    draft_id      TEXT NOT NULL,
    request_hash  TEXT NOT NULL,
    created_at    TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_drafts_workspace ON drafts(workspace);
"""


def _validate_workspace(ws: str) -> None:
    if not isinstance(ws, str) or not ws.strip():
        raise ValidationError("workspace must be a non-empty string")
    if len(ws) > 64:
        raise ValidationError("workspace too long (max 64)")


def _validate_team(team: int) -> None:
    if not isinstance(team, int) or isinstance(team, bool):
        raise ValidationError("owner_team must be an int")
    if team < 0 or team > 999:
        raise ValidationError("owner_team out of range [0,999]"

